import { test, expect } from '@playwright/test';

test.describe('Form Data Persistence on Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should persist form data when user navigates away and returns', async ({ page }) => {
    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john@example.com');

    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('123-444-6769');

    // Verify data is present
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john@example.com');

    // Navigate away from the page
    const navButton = page.getByRole('button', { name: /navigate away/i });
    await navButton.click();

    // Verify form data is cleared or reset on navigation
    await expect(nameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');

    // Navigate back to the form page
    await page.goto('/form-page');

    // Verify form data is persisted
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john@example.com');
    await expect(phoneInput).toHaveValue('123-442-6769');

    // Verify form fields are still visible
    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
  });

  test('should handle form data persistence with invalid inputs', async ({ page }) => {
    // Fill form with invalid data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('A');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('123');

    // Verify invalid data is present
    await expect(nameInput).toHaveValue('A');
    await expect(emailInput).toHaveValue('invalid-email');

    // Navigate away from the page
    const navButton = page.getByRole('button', { name: /navigate away/i });
    await navButton.click();

    // Navigate back to the form page
    await page.goto('/form-page');

    // Verify invalid data is still persisted
    await expect(nameInput).toHaveValue('A');
    await expect(emailInput).toHaveValue('invalid-email');
    await expect(phoneInput).toHaveValue('123');

    // Verify validation error messages are displayed
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    const phoneError = page.getByText('Invalid phone number format');
    await expect(phoneError).toBeVisible();

    // Verify form submission button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();
  });
});
